tool_calls:
cd /tmp && rm -f t1.db t2.db
# Test 1: triple-merge, no-space names, extra spaces, non-padded dates, users without orders
sqlite3 t1.db <<'EOF'
CREATE TABLE users(id INTEGER PRIMARY KEY, full_name TEXT NOT NULL, email TEXT NOT NULL, signup TEXT NOT NULL);
CREATE TABLE orders(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, total_cents INTEGER NOT NULL);
CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO meta VALUES ('schema_version', '1');
INSERT INTO users VALUES (10, '  x  y  z ', '  Foo@Bar.com', '1/2/2000');
INSERT INTO users VALUES (7, 'Mono', 'FOO@bar.COM ', '12/31/1999');
INSERT INTO users VALUES (12, 'A B', 'foo@bar.com', '03/09/2010');
INSERT INTO users VALUES (13, 'No Orders Here', 'solo@x.io', '11/11/2011');
INSERT INTO orders VALUES (1, 10, 5);
INSERT INTO orders VALUES (2, 7, 6);
INSERT INTO orders VALUES (3, 12, 7);
EOF
sqlite3 t1.db < /app/migrations/002_users_v2.sql
echo '--- t1 users ---'; sqlite3 t1.db "SELECT * FROM users;"
echo '--- t1 orders ---'; sqlite3 t1.db "SELECT * FROM orders ORDER BY id;"
echo '--- t1 meta ---'; sqlite3 t1.db "SELECT * FROM meta; PRAGMA integrity_check;"
# Test 2: empty users/orders tables
sqlite3 t2.db <<'EOF'
CREATE TABLE users(id INTEGER PRIMARY KEY, full_name TEXT NOT NULL, email TEXT NOT NULL, signup TEXT NOT NULL);
CREATE TABLE orders(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, total_cents INTEGER NOT NULL);
CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO meta VALUES ('schema_version', '1');
EOF
sqlite3 t2.db < /app/migrations/002_users_v2.sql
echo '--- t2 ---'; sqlite3 t2.db "SELECT * FROM users; SELECT * FROM orders; SELECT * FROM meta; PRAGMA integrity_check;"
echo '--- rerun-on-app.db should fail (already v2, sanity that file is one-way) ---'
sqlite3 /app/app.db < /app/migrations/002_users_v2.sql 2>&1 | head -2
sqlite3 /app/app.db "SELECT * FROM meta; SELECT COUNT(*) FROM users; SELECT COUNT(*) FROM orders;"

